/*
  ESP32 como servidor web: aloja la página del radar de vuelos y hace
  él mismo las peticiones a adsb.fi (evita problemas de CORS del navegador).

  No necesita la pantalla TFT ni TFT_eSPI ni ArduinoJson: solo actúa de
  "proxy" hacia adsb.fi y sirve una página HTML/JS que dibuja el radar en
  un <canvas>, igual que el preview.html, pero ahora corriendo en el propio
  ESP32. Así puedes abrirlo desde el navegador del móvil/PC mientras
  esperas la pantalla, y cuando la tengas, migras el dibujo de <canvas>
  a TFT_eSPI reutilizando este mismo backend.

  LIBRERÍAS NECESARIAS: ninguna extra, todo viene con el core de ESP32
  (WiFi.h, WebServer.h, HTTPClient.h, ESPmDNS.h).

  USO:
    1. Rellena WIFI_SSID / WIFI_PASS / HOME_LAT / HOME_LON / RADIUS_NM.
    2. Sube el sketch al ESP32.
    3. Abre el Monitor Serie (115200 baudios): te dirá la IP asignada,
       algo como 192.168.1.45.
    4. Desde cualquier navegador en la misma red, entra a
       http://192.168.1.45/  (o a http://flightradar.local/ si tu
       sistema soporta mDNS/Bonjour).
*/

#include <WiFi.h>
#include <WebServer.h>
#include <HTTPClient.h>
#include <ESPmDNS.h>

// ---------------------- CONFIGURACIÓN ----------------------
const char* WIFI_SSID = "Xiaomi_F8D1";
const char* WIFI_PASS = "WifiProhibidoALosQNoPaganDesde2023";

double HOME_LAT = 51.5719;
double HOME_LON = 4.7683;
double RADIUS_NM = 30.0;

const char* MDNS_NAME = "flightradar"; // http://flightradar.local/
// -------------------------------------------------------------

WebServer server(80);

// Página HTML/JS: el mismo radar del preview, pero pidiendo los datos
// a "/aircraft" (el propio ESP32) en vez de a adsb.fi directamente.
const char INDEX_HTML[] PROGMEM = R"rawliteral(
<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Radar de vuelos - ESP32</title>
<style>
  body { background:#111; color:#ddd; font-family:Arial,sans-serif; display:flex; flex-direction:column; align-items:center; padding:16px; }
  h1 { font-size:16px; color:#9be564; margin:4px 0; }
  .sub { color:#888; font-size:12px; margin-bottom:14px; }
  .screen-wrap { background:#000; border:8px solid #222; border-radius:12px; box-shadow:0 0 0 2px #444; }
  canvas { display:block; image-rendering:pixelated; }
  .status { font-size:12px; color:#999; margin-top:10px; }
  .controls { display:flex; gap:8px; margin-top:10px; flex-wrap:wrap; justify-content:center; }
  button { padding:6px 12px; background:#274d1e; color:#b7f296; border:1px solid #3d7a2c; border-radius:4px; cursor:pointer; font-size:12px; }
</style>
</head>
<body>
<h1>Radar de vuelos (ESP32)</h1>
<div class="sub">Datos vía adsb.fi, servidos por el propio ESP32</div>

<div class="screen-wrap"><canvas id="screen" width="320" height="240"></canvas></div>

<div class="controls">
  <button id="refreshBtn">Actualizar ahora</button>
  <button id="autoBtn">Auto-refresco: OFF</button>
</div>
<div class="status" id="status">Cargando...</div>

<script>
const canvas = document.getElementById('screen');
const ctx = canvas.getContext('2d');
let autoTimer = null;
let HOME_LAT = 0, HOME_LON = 0, DIST_NM = 30;

function toRad(d){return d*Math.PI/180;}
function toDeg(r){return r*180/Math.PI;}
function distanceNm(lat1,lon1,lat2,lon2){
  const R=3440.065;
  const dLat=toRad(lat2-lat1), dLon=toRad(lon2-lon1);
  const a=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLon/2)**2;
  return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
}
function bearingDeg(lat1,lon1,lat2,lon2){
  const y=Math.sin(toRad(lon2-lon1))*Math.cos(toRad(lat2));
  const x=Math.cos(toRad(lat1))*Math.sin(toRad(lat2))-Math.sin(toRad(lat1))*Math.cos(toRad(lat2))*Math.cos(toRad(lon2-lon1));
  return (toDeg(Math.atan2(y,x))+360)%360;
}

function drawRadar(aircraft){
  const w=canvas.width,h=canvas.height,cx=w/2,cy=h/2+6,maxR=Math.min(w,h)/2-20;
  ctx.fillStyle='#000'; ctx.fillRect(0,0,w,h);
  ctx.strokeStyle='#173a17'; ctx.fillStyle='#3a6b3a'; ctx.font='9px monospace'; ctx.textAlign='left';
  for(let i=1;i<=3;i++){
    const r=maxR*i/3;
    ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.stroke();
    ctx.fillText(Math.round(DIST_NM*i/3)+'nm', cx+3, cy-r+9);
  }
  ctx.beginPath();
  ctx.moveTo(cx-maxR,cy); ctx.lineTo(cx+maxR,cy);
  ctx.moveTo(cx,cy-maxR); ctx.lineTo(cx,cy+maxR);
  ctx.stroke();
  ctx.fillStyle='#5a8a5a'; ctx.textAlign='center';
  ctx.fillText('N',cx,cy-maxR-6); ctx.fillText('S',cx,cy+maxR+12);
  ctx.fillText('E',cx+maxR+8,cy+3); ctx.fillText('O',cx-maxR-8,cy+3);
  ctx.fillStyle='#e0c33c';
  ctx.beginPath(); ctx.moveTo(cx,cy-5); ctx.lineTo(cx-5,cy+3); ctx.lineTo(cx+5,cy+3); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#9be564'; ctx.textAlign='left'; ctx.font='10px monospace';
  ctx.fillText(aircraft.length+' vuelos',4,10);
  ctx.textAlign='right'; ctx.fillText(new Date().toLocaleTimeString(), w-4, 10);

  aircraft.forEach(ac=>{
    if(ac.lat==null||ac.lon==null) return;
    const d=distanceNm(HOME_LAT,HOME_LON,ac.lat,ac.lon);
    if(d>DIST_NM) return;
    const brg=bearingDeg(HOME_LAT,HOME_LON,ac.lat,ac.lon);
    const rad=toRad(brg);
    const px=cx+(d/DIST_NM)*maxR*Math.sin(rad);
    const py=cy-(d/DIST_NM)*maxR*Math.cos(rad);
    ctx.save(); ctx.translate(px,py); ctx.rotate(toRad(ac.track||0));
    ctx.fillStyle='#4ec9ff';
    ctx.beginPath(); ctx.moveTo(0,-4); ctx.lineTo(-3,3); ctx.lineTo(3,3); ctx.closePath(); ctx.fill();
    ctx.restore();
    ctx.fillStyle='#cfeeff'; ctx.font='8px monospace'; ctx.textAlign='left';
    const label=(ac.flight?ac.flight.trim():ac.hex)+' FL'+Math.round((ac.alt_baro||0)/100);
    ctx.fillText(label, px+5, py+3);
  });
}

async function fetchAndDraw(){
  document.getElementById('status').textContent='Consultando...';
  try{
    const res=await fetch('/aircraft');
    if(!res.ok) throw new Error('HTTP '+res.status);
    const data=await res.json();
    HOME_LAT=data.home_lat; HOME_LON=data.home_lon; DIST_NM=data.dist_nm;
    drawRadar(data.ac||[]);
    document.getElementById('status').textContent='Actualizado '+new Date().toLocaleTimeString()+' · '+(data.ac||[]).length+' aeronaves';
  }catch(err){
    document.getElementById('status').textContent='Error: '+err.message;
  }
}

document.getElementById('refreshBtn').addEventListener('click', fetchAndDraw);
document.getElementById('autoBtn').addEventListener('click', (e)=>{
  if(autoTimer){
    clearInterval(autoTimer); autoTimer=null;
    e.target.textContent='Auto-refresco: OFF';
  }else{
    autoTimer=setInterval(fetchAndDraw, 15000);
    e.target.textContent='Auto-refresco: ON (15s)';
  }
});

fetchAndDraw();
</script>
</body>
</html>
)rawliteral";

void handleRoot() {
  server.send_P(200, "text/html", INDEX_HTML);
}

void handleAircraft() {
  if (WiFi.status() != WL_CONNECTED) {
    server.send(503, "application/json", "{\"error\":\"wifi\"}");
    return;
  }

  HTTPClient http;
  String url = "https://opendata.adsb.fi/api/v2/lat/" + String(HOME_LAT, 4) +
               "/lon/" + String(HOME_LON, 4) +
               "/dist/" + String((int)RADIUS_NM);
  http.begin(url);
  int code = http.GET();

  if (code == 200) {
    String payload = http.getString();
    http.end();

    // Reempaquetamos: añadimos home_lat/home_lon/dist_nm para que el
    // navegador no tenga que conocerlos por separado, y renombramos
    // el array "ac" tal cual viene de adsb.fi.
    String out = "{\"home_lat\":" + String(HOME_LAT, 4) +
                 ",\"home_lon\":" + String(HOME_LON, 4) +
                 ",\"dist_nm\":" + String(RADIUS_NM, 1) +
                 ",\"ac\":" + extractAcArray(payload) + "}";
    server.send(200, "application/json", out);
  } else {
    http.end();
    server.send(502, "application/json", "{\"error\":\"adsb.fi HTTP " + String(code) + "\"}");
  }
}

// Extrae solo el array "ac":[...] del JSON de adsb.fi sin necesitar
// una librería de parseo JSON (para ahorrar RAM en el ESP32).
String extractAcArray(const String& json) {
  int keyPos = json.indexOf("\"ac\"");
  if (keyPos == -1) return "[]";
  int bracketStart = json.indexOf('[', keyPos);
  if (bracketStart == -1) return "[]";

  int depth = 0;
  for (int i = bracketStart; i < (int)json.length(); i++) {
    if (json[i] == '[') depth++;
    else if (json[i] == ']') {
      depth--;
      if (depth == 0) {
        return json.substring(bracketStart, i + 1);
      }
    }
  }
  return "[]";
}

void setup() {
  Serial.begin(115200);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("Conectando WiFi");
  while (WiFi.status() != WL_CONNECTED) {
    delay(400);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Conectado. IP: ");
  Serial.println(WiFi.localIP());

  if (MDNS.begin(MDNS_NAME)) {
    Serial.print("También accesible en: http://");
    Serial.print(MDNS_NAME);
    Serial.println(".local/");
  }

  server.on("/", handleRoot);
  server.on("/aircraft", handleAircraft);
  server.begin();
  Serial.println("Servidor web iniciado.");
}

void loop() {
  server.handleClient();
}
